import time
from functools import wraps

def rate_limiter(max_calls, period=1.0):
    def decorator(func):
        calls = []

        @wraps(func)
        def wrapper(*args, **kwargs):
            now = time.time()
            calls[:] = [t for t in calls if now - t < period]
            if len(calls) >= max_calls:
                raise Exception(f"Rate limit exceeded: max {max_calls} calls per {period}s")
            calls.append(now)
            return func(*args, **kwargs)

        return wrapper
    return decorator

@rate_limiter(max_calls=3, period=1.0)
def fetch_data():
    return "data"

import time
import threading
from functools import wraps

def rate_limiter(max_calls, period=1.0):
    def decorator(func):
        calls = []
        lock = threading.Lock()

        @wraps(func)
        def wrapper(*args, **kwargs):
            while True:
                with lock:
                    now = time.time()
                    calls[:] = [t for t in calls if now - t < period]
                    if len(calls) < max_calls:
                        calls.append(now)
                        break
                    wait_time = period - (now - calls[0])
                time.sleep(max(wait_time, 0))
            return func(*args, **kwargs)

        return wrapper
    return decorator

