# Test 1: Global rate limiting allows up to max_calls
import time
call_times = []
@rate_limiter(max_calls=3, period=1.0)
def fn():
    call_times.append(time.time())
    return True
for _ in range(3):
    assert fn() == True

# Test 2: max_wait raises RateLimitError when limit hit and wait too long
@rate_limiter(max_calls=1, period=2.0, max_wait=0.1)
def fn2():
    return True
fn2()  # first call succeeds
try:
    fn2()  # second call should raise immediately
    assert False, 'Expected RateLimitError'
except RateLimitError:
    pass

# Test 3: Per-key limiting — different keys don't share quota
results = []
@rate_limiter(max_calls=2, period=1.0, max_wait=0.1, key=lambda uid: uid)
def fn3(uid):
    results.append(uid)
    return uid
fn3('a')
fn3('a')
fn3('b')  # should not be blocked by 'a' quota
fn3('b')
assert results == ['a', 'a', 'b', 'b']

# Test 4: key=None behaves as global (backward compatible)
@rate_limiter(max_calls=2, period=1.0, max_wait=0.0)
def fn4(x):
    return x
fn4(1)
fn4(2)
try:
    fn4(3)
    assert False
except RateLimitError:
    pass
